mapper.select:
SELECT * FROM skill_metadata
WHERE skill_id = #{skillId}
  AND (
      creator_id = #{userId}
      OR visibility = 'PUBLIC'
      OR (visibility = 'TENANT' AND tenant_id = #{tenantId})
      OR JSON_CONTAINS(allowed_user_ids, '"' + #{userId} + '"')
  )
LIMIT 1
